CREATE TABLE IF NOT EXISTS listing_reviews(id TEXT PRIMARY KEY,screening_id TEXT NOT NULL UNIQUE REFERENCES screenings(id),requested_by TEXT NOT NULL REFERENCES accounts(id),cycle_label TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,listing_url TEXT NOT NULL,valid_until TEXT NOT NULL,created INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN('pending','assigned','completed','withdrawn')),assignee TEXT REFERENCES accounts(id),phone_outcome TEXT NOT NULL DEFAULT 'not_checked',registration TEXT NOT NULL DEFAULT '',review_note TEXT NOT NULL DEFAULT '',reviewed_at INTEGER,withdrawn_at INTEGER,withdrawal_reason TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS listing_review_reports(id TEXT PRIMARY KEY,review_id TEXT NOT NULL REFERENCES listing_reviews(id),reporter TEXT NOT NULL REFERENCES accounts(id),body TEXT NOT NULL,created INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'open',resolution TEXT NOT NULL DEFAULT '',resolved_at INTEGER);
CREATE TRIGGER IF NOT EXISTS listing_review_no_delete BEFORE DELETE ON listing_reviews BEGIN SELECT RAISE(ABORT,'review_history_retained'); END;
CREATE TRIGGER IF NOT EXISTS listing_review_scope_immutable BEFORE UPDATE ON listing_reviews WHEN OLD.id IS NOT NEW.id OR OLD.screening_id IS NOT NEW.screening_id OR OLD.requested_by IS NOT NEW.requested_by OR OLD.cycle_label IS NOT NEW.cycle_label OR OLD.phone IS NOT NEW.phone OR OLD.address IS NOT NEW.address OR OLD.listing_url IS NOT NEW.listing_url OR OLD.valid_until IS NOT NEW.valid_until OR OLD.created IS NOT NEW.created BEGIN SELECT RAISE(ABORT,'review_scope_immutable'); END;
CREATE TRIGGER IF NOT EXISTS listing_review_findings_immutable BEFORE UPDATE ON listing_reviews WHEN OLD.reviewed_at IS NOT NULL AND (OLD.reviewed_at IS NOT NEW.reviewed_at OR OLD.phone_outcome IS NOT NEW.phone_outcome OR OLD.registration IS NOT NEW.registration OR OLD.review_note IS NOT NEW.review_note) BEGIN SELECT RAISE(ABORT,'review_findings_immutable'); END;
CREATE TRIGGER IF NOT EXISTS listing_report_no_delete BEFORE DELETE ON listing_review_reports BEGIN SELECT RAISE(ABORT,'report_history_retained'); END;
CREATE TRIGGER IF NOT EXISTS listing_report_original_immutable BEFORE UPDATE ON listing_review_reports WHEN OLD.id IS NOT NEW.id OR OLD.review_id IS NOT NEW.review_id OR OLD.reporter IS NOT NEW.reporter OR OLD.body IS NOT NEW.body OR OLD.created IS NOT NEW.created BEGIN SELECT RAISE(ABORT,'report_original_immutable'); END;
